escenas.animacion:
const W=A.W, ac=A.accent, red='#FF3B3B', pal=A.pal||{};
const pale=pal.paleBlue||'#9fc3ff', navy=pal.navy||'#0d1a3a';
A.bg('#0b1226','#050914');
const kA=A.k('AirTag',0.333), kG=A.k('GPS',1.333), kAun=A.k('aun',2.0), kDonde=A.k('dónde',3.333), kMal=A.k('maleta',4.333), kOtro=A.k('otro',5.0), kMundo=A.k('mundo',6.0);
const kX=Math.max(1.1,kG-0.15);

function mix(a,b,p){const h=s=>[1,3,5].map(i=>parseInt(s.slice(i,i+2),16));const x=h(a),y=h(b);return 'rgb('+x.map((v,i)=>Math.round(v+(y[i]-v)*p)).join(',')+')';}
function airtag(x,y,s,alpha){
  if(s<=0.01) return;
  ctx.save(); ctx.globalAlpha=alpha==null?1:alpha;
  A.circle(x,y,80*s,{fill:'#f4f6fa',glow:ac});
  A.circle(x,y,62*s,{stroke:'#c9d0dc',lw:3*s});
  A.circle(x,y,86*s,{stroke:ac,lw:6*s});
  A.circle(x,y,14*s,{fill:'#c9d0dc'});
  ctx.restore();
}
function satellite(x,y,a,g){
  const panel=mix('#1e3a6e','#3a3f48',g), pst=mix('#9fc3ff','#8a8f98',g), body=mix('#cfd8e8','#9a9ea6',g), wh=mix('#ffffff','#b0b3b8',g);
  ctx.save(); ctx.globalAlpha=a;
  for(const d of [-1,1]){
    const px=x+d*120;
    A.rect(px-70,y-32,140,64,{r:6,fill:panel,stroke:pst,lw:3});
    for(let i=1;i<4;i++) A.line([[px-70+i*35,y-32],[px-70+i*35,y+32]],{stroke:pst,lw:2,alpha:0.6});
    A.line([[x+d*40,y],[x+d*50,y]],{stroke:pst,lw:4});
  }
  A.rect(x-40,y-40,80,80,{r:10,fill:body,stroke:wh,lw:3});
  A.line([[x,y+40],[x,y+62]],{stroke:wh,lw:4});
  A.circle(x,y+66,10,{fill:wh});
  ctx.restore();
}
function suitcase(){
  A.rect(-170,-120,340,250,{r:30,fill:'#22304f',stroke:ac,lw:7});
  if(A.lib&&A.lib.hatch) A.lib.hatch(ctx,[[-160,-110],[160,-110],[160,120],[-160,120]],{angle:-0.8,spacing:16,width:2,color:'rgba(255,212,0,0.18)'});
  A.line([[-70,-120],[-70,-175],[70,-175],[70,-120]],{stroke:ac,lw:10});
  A.line([[-100,-120],[-100,130]],{stroke:ac,lw:5,alpha:0.6});
  A.line([[100,-120],[100,130]],{stroke:ac,lw:5,alpha:0.6});
  A.circle(-110,150,16,{fill:'#0b1226',stroke:ac,lw:4});
  A.circle(110,150,16,{fill:'#0b1226',stroke:ac,lw:4});
  A.line([[60,-175],[130,-100]],{stroke:'#ffffff',lw:3,alpha:0.8});
}

// ---- GLOBO ----
const pG=A.p(kOtro-0.15,0.9,'snapSettle');
const GX=540, GY=800, GR=300*pG;
if(GR>2){
  const g=ctx.createRadialGradient(GX-90,GY-110,20,GX,GY,GR);
  g.addColorStop(0,'#1d3c7a'); g.addColorStop(1,navy);
  ctx.beginPath(); ctx.arc(GX,GY,GR,0,Math.PI*2); ctx.fillStyle=g; ctx.fill();
  const rot=t*0.7;
  ctx.save(); ctx.beginPath(); ctx.arc(GX,GY,GR,0,Math.PI*2); ctx.clip();
  const R=A.rand(7);
  for(let i=0;i<9;i++){
    const lon=R()*6.28, lat=(R()-0.5)*2.2, sz=0.1+R()*0.12;
    const L=lon+rot, c=Math.cos(L);
    if(c>0){
      const bx=GX+GR*Math.cos(lat)*Math.sin(L), by=GY-GR*Math.sin(lat);
      ctx.beginPath(); ctx.ellipse(bx,by,GR*sz*c+2,GR*sz*0.7,0,0,Math.PI*2);
      ctx.fillStyle='rgba(159,195,255,0.28)'; ctx.fill();
    }
  }
  ctx.strokeStyle='rgba(159,195,255,0.35)'; ctx.lineWidth=2;
  for(let m=0;m<6;m++){
    const ph=rot+m*Math.PI/6, rx=Math.abs(Math.cos(ph))*GR;
    ctx.beginPath(); ctx.ellipse(GX,GY,rx,GR,0,0,Math.PI*2); ctx.stroke();
  }
  for(const la of [-0.6,-0.3,0,0.3,0.6]){
    ctx.beginPath(); ctx.ellipse(GX,GY+la*GR,GR*Math.sqrt(1-la*la),GR*0.12*Math.sqrt(1-la*la),0,0,Math.PI*2); ctx.stroke();
  }
  ctx.restore();
  A.circle(GX,GY,GR,{stroke:pale,lw:5});
}

// ---- SATÉLITE GPS (tachado, gris, sale a 2.8s) ----
const pSin=A.p(kA+0.2,0.6,'snapSettle');
const pGray=A.p(kX+0.45,0.5,'softInOut');
const pSout=A.p(2.8,0.5,'accelExit');
const base=pSin*(1-pSout);
if(base>0.01){
  const pSh=A.p(kX+0.3,0.45,'cruise');
  const shake=(t>kX+0.3)?14*(1-pSh)*Math.sin(t*70):0;
  const sx=540+shake, sy=A.lerp(480,570,pSin)-pSout*240;
  const satA=base*(1-0.6*pGray);
  if(t<kX) A.rings(540,sy+70,kA+0.6,{count:3,speed:180,gap:0.35,maxR:240,color:pale,lw:3,alpha:0.5*base});
  satellite(sx,sy,satA,pGray);
  A.text('GPS',sx,sy-80,{size:58,weight:'900',color:mix('#ffffff','#9a9ea6',pGray),align:'center',alpha:satA});
  // tachado de la etiqueta
  const pT=A.p(kX+0.15,0.25,'crashIn');
  if(pT>0) A.line([[sx-75,sy-98],[sx+75,sy-98]],{stroke:red,lw:10,progress:pT,alpha:base});
  // X roja grande sobre el satélite
  const pX1=A.p(kX,0.22,'crashIn'), pX2=A.p(kX+0.1,0.22,'crashIn');
  if(pX1>0){
    A.line([[sx-80,sy-80],[sx+80,sy+80]],{stroke:red,lw:14,progress:pX1,alpha:base});
    if(pX2>0) A.line([[sx+80,sy-80],[sx-80,sy+80]],{stroke:red,lw:14,progress:pX2,alpha:base});
  }
}
if(t>kX+0.1 && t<kX+0.45) A.flash(kX+0.1,0.3,0.2);

// ---- GRUPO MALETA ----
const popS=t>=kMal-0.1?A.pop(kMal-0.1,0.5):0;
const pZ=A.p(kOtro-0.1,0.9,'whip');
const gx=A.lerp(540,700,pZ), gy=A.lerp(830,650,pZ), gs=A.lerp(1,0.26,pZ)*popS;
if(gs>0.01){
  ctx.save(); ctx.translate(gx,gy); ctx.scale(gs,gs); suitcase(); ctx.restore();
}

// ---- AIRTAG ----
const pIn=A.pop(kA-0.05,0.5);
const pAt=A.p(kMal-0.05,0.4,'glide');
const tagX=gx+gs*135, tagY=gy-gs*95;
const bob=Math.sin(t*3)*6*(1-pAt);
const beat=1+0.08*Math.max(0,1-A.p(kAun,0.4,'cruise'))*(t>=kAun?1:0)+0.06*Math.max(0,1-A.p(kDonde,0.35,'cruise'))*(t>=kDonde?1:0);
const kPulse=kMal+0.3;
const pulse=(t>=kPulse)?1+0.35*Math.sin(Math.PI*A.p(kPulse,0.4,'cruise')):1;
const ax=A.lerp(540,tagX,pAt), ay=A.lerp(880+bob,tagY,pAt);
const as=A.lerp(1.7*beat,0.62*Math.max(gs,0.2),pAt)*pIn*pulse;
if(t>=kAun && t<kMal) A.rings(ax,ay,kAun,{count:3,speed:220,gap:0.45,maxR:320,color:ac,lw:4,alpha:0.55});
if(t>=kPulse && t<kPulse+0.9) A.rings(ax,ay,kPulse,{count:2,speed:260,gap:0.2,maxR:200,color:ac,lw:6,alpha:0.85});
airtag(ax,ay,as,1);

// ---- ¿DÓNDE? ----
const pD=A.p(kDonde,0.45,'softLand'), pDout=A.p(kOtro-0.2,0.4,'accelExit');
if(pD>0 && pDout<1){
  A.label('¿DÓNDE?',540,1440,{size:64,bg:ac,color:'#0b1226',scale:A.pop(kDonde,0.45),alpha:1-pDout});
}

// ---- TELÉFONO + ARCO (curvado a la derecha) ----
const pPh=A.p(kOtro+0.05,0.5,'snapSettle');
if(pPh>0){
  const px=300, py=A.lerp(1680,1540,pPh);
  ctx.save(); ctx.globalAlpha=pPh;
  A.rect(px-60,py-110,120,220,{r:22,fill:'#111a30',stroke:'#ffffff',lw:5});
  A.rect(px-46,py-92,92,170,{r:10,fill:'#1d3c7a'});
  A.circle(px,py-10,12,{fill:ac,glow:ac});
  ctx.restore();

  const P=[[px,py-115],[640,1400],[900,1235],[935,990],[830,760],[700,645]];
  const pts=[];
  for(let i=0;i<P.length-1;i++){
    const p0=P[Math.max(0,i-1)],p1=P[i],p2=P[i+1],p3=P[Math.min(P.length-1,i+2)];
    for(let j=0;j<14;j++){
      const u=j/14,u2=u*u,u3=u2*u;
      pts.push([0.5*(2*p1[0]+(-p0[0]+p2[0])*u+(2*p0[0]-5*p1[0]+4*p2[0]-p3[0])*u2+(-p0[0]+3*p1[0]-3*p2[0]+p3[0])*u3),
                0.5*(2*p1[1]+(-p0[1]+p2[1])*u+(2*p0[1]-5*p1[1]+4*p2[1]-p3[1])*u2+(-p0[1]+3*p1[1]-3*p2[1]+p3[1])*u3)]);
    }
  }
  pts.push(P[P.length-1]);
  let tot=0; const segL=[];
  for(let i=1;i<pts.length;i++){const l=Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]);segL.push(l);tot+=l;}
  const pL=A.p(kOtro+0.3,0.8,'glide');
  if(pL>0){
    let rem=pL*tot; const part=[pts[0]];
    for(let i=1;i<pts.length&&rem>0;i++){
      const l=segL[i-1];
      if(rem>=l){part.push(pts[i]);rem-=l;}
      else{const f=rem/l;part.push([A.lerp(pts[i-1][0],pts[i][0],f),A.lerp(pts[i-1][1],pts[i][1],f)]);rem=0;}
    }
    const strokeIt=(clip,alpha)=>{
      ctx.save(); ctx.beginPath(); clip(); ctx.clip();
      ctx.globalAlpha=alpha; ctx.strokeStyle=ac; ctx.lineWidth=5; ctx.lineCap='round'; ctx.setLineDash([18,14]);
      ctx.beginPath(); ctx.moveTo(part[0][0],part[0][1]); for(const q of part) ctx.lineTo(q[0],q[1]); ctx.stroke();
      ctx.restore();
    };
    strokeIt(()=>{ctx.rect(0,0,W,1150);ctx.rect(0,1310,W,A.H-1310);},0.9);
    strokeIt(()=>{ctx.rect(0,1150,W,160);},0.45);
    const tip=part[part.length-1];
    if(pL<1) A.circle(tip[0],tip[1],9,{fill:ac,glow:ac});
    // contador sincronizado con la línea
    const num=A.counter(0,9888,pL,0).replace(/\D/g,'').replace(/\B(?=(\d{3})+(?!\d))/g,'.');
    const sc=pL>=1?A.pop(kOtro+1.1,0.35):1;
    A.text(num+' km',680,1610,{size:80*sc,weight:'900',color:pL>=1?ac:'#ffffff',align:'center',alpha:A.clamp(pL*4)});
  }
}

// ---- PIN ----
if(t>=kMundo-0.35){
  const ps=A.pop(kMundo-0.35,0.45);
  const px=700, py=640-80*ps;
  A.rings(700,640,kMundo-0.1,{count:3,speed:200,gap:0.3,maxR:180,color:ac,lw:5,alpha:0.8});
  ctx.save(); ctx.translate(px,py); ctx.scale(ps,ps);
  ctx.beginPath(); ctx.moveTo(0,60); ctx.bezierCurveTo(-55,0,-50,-55,0,-55); ctx.bezierCurveTo(50,-55,55,0,0,60);
  ctx.fillStyle=ac; ctx.shadowColor=ac; ctx.shadowBlur=30; ctx.fill(); ctx.shadowBlur=0;
  ctx.beginPath(); ctx.arc(0,-18,18,0,Math.PI*2); ctx.fillStyle='#0b1226'; ctx.fill();
  ctx.restore();
}

const ac = A.accent;
A.bg('#05101a', '#0b2233');
const cx = 540, cy = 740;
const kEm = A.k('emitir', 1.333), kPeq = A.k('pequeña', 2.0), kSen = A.k('señal', 2.333);
const kBt = A.k('Bluetooth', 2.667), kSus = A.k('susurro', 3.667), kCon = A.k('constante', 4.0);
const PER = 0.55;
const pulses = [];
for (let n = 0; n < 14; n++) pulses.push(kEm + n * PER);

// ---- ondas ----
const thin = A.p(kPeq, 0.5, 'softInOut');
const soft = A.p(kSus, 0.5, 'softInOut');
pulses.forEach((t0) => {
  const age = t - t0;
  if (age < 0 || age > 2.2) return;
  const r = 165 + age * 290;
  const a = Math.pow(1 - age / 2.2, 1.4) * A.lerp(0.9, 0.45, soft);
  ctx.save();
  ctx.globalAlpha = a;
  ctx.strokeStyle = ac;
  ctx.lineWidth = A.lerp(9, 3.5, thin);
  ctx.shadowColor = ac; ctx.shadowBlur = 20;
  if (soft > 0.5) ctx.setLineDash([18, 14]);
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
  ctx.restore();
});

// ---- AirTag ----
let beat = 0;
pulses.forEach((t0) => { const d = t - t0; if (d >= 0 && d < 0.4) beat = Math.max(beat, Math.exp(-d * 9)); });
const sc = A.pop(0.1, 0.55) * (1 + 0.045 * beat);
const fy = Math.sin(t * 2.2) * 8;
A.with(() => {
  const R = 150;
  ctx.save();
  ctx.globalAlpha = 0.35; ctx.fillStyle = '#000';
  ctx.beginPath(); ctx.ellipse(cx, cy + R + 40, R * 0.8, 18, 0, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
  const g = ctx.createRadialGradient(cx - 50, cy - 60, 20, cx, cy, R);
  g.addColorStop(0, '#ffffff'); g.addColorStop(0.7, '#e6eef2'); g.addColorStop(1, '#aab8c2');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();
  const pts = [];
  for (let i = 0; i < 24; i++) { const an = Math.PI * 0.1 + i / 23 * Math.PI * 0.8; pts.push([cx + Math.cos(an) * R * 0.98, cy + Math.sin(an) * R * 0.98]); }
  A.lib.hatch(ctx, pts, { angle: -0.7, spacing: 12, width: 1.5, color: 'rgba(60,80,100,0.35)' });
  A.circle(cx, cy, R, { stroke: '#ffffff', lw: 4 });
  const g2 = ctx.createRadialGradient(cx - 20, cy - 25, 5, cx, cy, R * 0.55);
  g2.addColorStop(0, '#f4f7f9'); g2.addColorStop(1, '#9fb0bb');
  ctx.fillStyle = g2; ctx.beginPath(); ctx.arc(cx, cy, R * 0.55, 0, Math.PI * 2); ctx.fill();
  A.circle(cx, cy, R * 0.55, { stroke: '#7d8e99', lw: 2 });
  const on = A.p(kEm - 0.1, 0.3, 'softLand');
  A.lib.glowDot(ctx, cx, cy, 10 + 14 * beat, { color: ac, alpha: on * (0.5 + 0.5 * beat) });
}, { x: cx, y: cy, scale: sc });

// ---- insignia Bluetooth ----
const bs = A.pop(kBt, 0.45);
if (bs > 0) {
  const bx = cx + 130, by = cy - 140 + fy * 0.5;
  A.with(() => {
    A.circle(bx, by, 52, { fill: ac, glow: 25 });
    ctx.save();
    ctx.strokeStyle = '#05101a'; ctx.lineWidth = 8; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(bx - 18, by - 16); ctx.lineTo(bx + 18, by + 16); ctx.lineTo(bx, by + 32);
    ctx.lineTo(bx, by - 32); ctx.lineTo(bx + 18, by - 16); ctx.lineTo(bx - 18, by + 16);
    ctx.stroke(); ctx.restore();
  }, { x: bx, y: by, scale: bs });
}

// ---- etiqueta principal ----
const ls = A.pop(kSen, 0.45);
if (ls > 0) A.label('SEÑAL BLUETOOTH', cx, 1060, { size: 54, bg: ac, color: '#05101a', scale: ls });

// ---- tren de pulsos (constante) ----
const tr = A.p(kSus - 0.2, 0.5, 'softLand');
if (tr > 0) {
  const y0 = 1580, x0 = 140, x1 = 940, spd = 420;
  ctx.save();
  ctx.globalAlpha = tr;
  ctx.strokeStyle = 'rgba(255,255,255,0.15)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y0); ctx.stroke();
  ctx.strokeStyle = ac; ctx.lineWidth = 5; ctx.shadowColor = ac; ctx.shadowBlur = 14;
  ctx.beginPath();
  const xEnd = A.lerp(x0, x1, A.p(kSus - 0.2, 0.6, 'glide'));
  for (let x = x0; x <= xEnd; x += 4) {
    const tau = t - (x1 - x) / spd;
    let s = 0;
    pulses.forEach((p) => { const d = tau - p; s += Math.exp(-d * d / 0.0012); });
    const y = y0 - s * 70;
    if (x === x0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.stroke(); ctx.restore();
  A.circle(x1, y0, 8 + 6 * beat, { fill: ac, alpha: tr, glow: 20 });
}
const cs = A.pop(kCon, 0.45);
if (cs > 0) A.text('CONSTANTE', 540, 1440, { size: 64, color: '#ffffff', weight: 800, align: 'center', alpha: A.clamp(cs) });

const W=A.W, ac=A.accent, MAG='#FF3EA5', S=1.15;
A.bg('#0b1a2e','#050b16');
const kIph=A.k('iPhone',0.333), kIpad=A.k('iPad',0.667), kMac=A.k('Mac',1.333), kPase=A.k('pase',2.0), kEsc=A.k('escucha',2.667), kSus=A.k('susurro',3.333), kNo=A.k('no',4.0);
const tx=680, ty=860;
// ---- susurro: ondas continuas del AirTag
for(let i=0;i<4;i++){const ph=((t*0.75+i/4)%1);const r=90+ph*440;A.circle(tx,ty,r,{stroke:ac,lw:4,alpha:(1-ph)*0.5});}
// AirTag
const tagS=S*(1+0.03*Math.sin(t*6));
A.with(()=>{
  A.circle(tx,ty,74,{fill:'#f4f6fa',glow:ac});
  A.lib.hatch(ctx,[[tx+10,ty-70],[tx+74,ty],[tx+10,ty+70],[tx+40,ty]],{angle:0.8,spacing:9,width:2,color:'rgba(40,60,90,0.35)'});
  A.circle(tx,ty,54,{stroke:'#b9c3d3',lw:4});
  A.circle(tx,ty,10,{fill:'#9aa6b8'});
},{x:tx,y:ty,scale:tagS*A.pop(0,0.4)});
// ---- dibujos de equipos
function phone(x,y,s,on,al){A.with(()=>{
  A.rect(x-36,y-70,72,140,{r:14,fill:'#111c2e',stroke:'#ffffff',lw:4});
  A.rect(x-27,y-58,54,116,{r:6,fill:'#1d3050'});
  if(on>0){A.rect(x-27,y-58,54,116,{r:6,fill:ac,alpha:on*0.9,glow:ac});
    for(let j=1;j<=3;j++){ctx.save();ctx.globalAlpha=on*al;ctx.strokeStyle='#0b1a2e';ctx.lineWidth=5;ctx.beginPath();ctx.arc(x-12,y+8,j*11,-0.9,0.9);ctx.stroke();ctx.restore();}}
},{x,y,scale:s,alpha:al});}
function ipad(x,y,s,al){A.with(()=>{A.rect(x-70,y-90,140,180,{r:14,fill:'#111c2e',stroke:'#ffffff',lw:4});A.rect(x-58,y-78,116,156,{r:6,fill:'#1d3050'});},{x,y,scale:s,alpha:al});}
function mac(x,y,s,al){A.with(()=>{A.rect(x-100,y-75,200,130,{r:10,fill:'#111c2e',stroke:'#ffffff',lw:4});A.rect(x-88,y-63,176,106,{r:4,fill:'#1d3050'});A.rect(x-125,y+58,250,16,{r:6,fill:'#dfe5ee'});},{x,y,scale:s,alpha:al});}
// ---- fila de equipos (borde superior en y=420)
const dim=A.lerp(1,0.6,A.p(kPase,0.5,'softInOut'));
const IPH=[195,501], IPD=[600,524], MAC=[900,506];
phone(IPH[0],IPH[1],S*A.pop(kIph),0,dim);
ipad(IPD[0],IPD[1],S*A.pop(kIpad),dim);
mac(MAC[0],MAC[1],S*A.pop(kMac),dim);
[['iPhone',IPH[0],kIph],['iPad',IPD[0],kIpad],['Mac',MAC[0],kMac]].forEach(([s,x,k])=>{
  if(t>k)A.text(s,x,680,{size:42,weight:800,color:'#ffffff',align:'center',alpha:A.p(k,0.4,'softLand')*dim});
});
// ---- entrada del desconocido
const wp=A.p(kPase,0.9,'glide');
const px=A.lerp(-180,250,wp), fy=1120, oy=fy-1110;
const hx=px+85*S, hy=fy-205*S;
if(t>kPase-0.05){
  A.with(()=>{
    const sw=Math.sin(t*13)*0.45*(1-wp);
    const col=t>kNo?MAG:'#ffffff';
    A.line([[px,1000+oy],[px+Math.sin(sw)*110,1110+oy]],{stroke:'#fff',lw:9});
    A.line([[px,1000+oy],[px-Math.sin(sw)*110,1110+oy]],{stroke:'#fff',lw:9});
    A.line([[px,905+oy],[px,1000+oy]],{stroke:'#fff',lw:10});
    A.line([[px,925+oy],[px+45,960+oy],[px+75,935+oy]],{stroke:'#fff',lw:8});
    A.line([[px,925+oy],[px-30,985+oy]],{stroke:'#fff',lw:8});
